118→func handleLifecycleTurnStart(ctx context.Context, ag agent.Agent, event *agent.Event) error {
119→	logCtx := logging.WithAgent(logging.WithComponent(ctx, "lifecycle"), ag.Name())
120→	logging.Info(logCtx, "turn-start",
121→		slog.String("event", event.Type.String()),
122→		slog.String("session_id", event.SessionID),
123→		slog.String("session_ref", event.SessionRef),
124→		slog.String("model", event.Model),
125→	)
126→
127→	sessionID := event.SessionID
128→	if sessionID == "" {
129→		return fmt.Errorf("no session_id in %s event", event.Type)
130→	}
131→	if err := validation.ValidateSessionID(sessionID); err != nil {
132→		return fmt.Errorf("invalid %s event: %w", event.Type, err)
133→	}
134→
135→	// Capture pre-prompt state (including transcript position via TranscriptAnalyzer)
136→	if err := CapturePrePromptState(ctx, ag, sessionID, event.SessionRef); err != nil {
137→		return err
138→	}
139→
140→	// Append prompt to prompt.txt on filesystem so it's available for
141→	// mid-turn commits (before SaveStep writes it to the shadow branch).
142→	// Prompts are separated by "\n\n---\n\n" to support multiple turns.
143→	if event.Prompt != "" {
144→		sessionDir := paths.SessionMetadataDirFromSessionID(sessionID)
145→		if sessionDirAbs, absErr := paths.AbsPath(ctx, sessionDir); absErr == nil {
146→			if mkErr := os.MkdirAll(sessionDirAbs, 0o750); mkErr == nil {
147→				promptPath := filepath.Join(sessionDirAbs, paths.PromptFileName)
148→				existing, readErr := os.ReadFile(promptPath) //nolint:gosec // session metadata path
149→				var content string
150→				if readErr == nil && len(existing) > 0 {
151→					content = string(existing) + "\n\n---\n\n" + event.Prompt
152→				} else {
153→					content = event.Prompt
154→				}
155→				if writeErr := os.WriteFile(promptPath, []byte(content), 0o600); writeErr != nil {
156→					logging.Warn(logCtx, "failed to write prompt.txt",
157→						slog.String("error", writeErr.Error()))
158→				}
159→			}
160→		}
161→	}
162→
163→	// Ensure strategy setup and initialize session
164→	if err := strategy.EnsureSetup(ctx); err != nil {
165→		logging.Warn(logCtx, "failed to ensure strategy setup",
166→			slog.String("error", err.Error()))
167→	}
168→
169→	strat := GetStrategy(ctx)
170→	if err := strat.InitializeSession(ctx, sessionID, ag.Type(), event.SessionRef, event.Prompt, event.Model); err != nil {
171→		logging.Warn(logCtx, "failed to initialize session state",
172→			slog.String("error", err.Error()))
173→	}
174→
175→	return nil
176→}
