54→// benchStatus returns a benchmark function for the `entire status` command.
55→// When useGitCommonDirCache is false, it clears the git common dir cache each
56→// iteration to simulate the old uncached behavior.
57→func benchStatus(sessionCount int, detailed, useGitCommonDirCache bool) func(*testing.B) {
58→	return func(b *testing.B) {
59→		repo := benchutil.NewBenchRepo(b, benchutil.RepoOpts{})
60→
61→		// Create active session state files in .git/entire-sessions/
62→		for range sessionCount {
63→			repo.CreateSessionState(b, benchutil.SessionOpts{})
64→		}
65→
66→		// runStatus uses paths.WorktreeRoot() which requires cwd to be in the repo.
67→		b.Chdir(repo.Dir)
68→		paths.ClearWorktreeRootCache()
69→		session.ClearGitCommonDirCache()
70→
71→		b.ResetTimer()
72→		for range b.N {
73→			// Always clear WorktreeRoot to simulate a fresh CLI invocation.
74→			paths.ClearWorktreeRootCache()
75→
76→			if !useGitCommonDirCache {
77→				// Simulate old behavior: no git common dir cache.
78→				session.ClearGitCommonDirCache()
79→			}
80→
81→			if err := runStatus(context.Background(), io.Discard, detailed); err != nil {
82→				b.Fatalf("runStatus: %v", err)
83→			}
84→		}
85→	}
86→}
