1748→		if model != "" {
1749→			state.ModelName = model
1750→		}
1751→
1752→		// Update LastPrompt on every turn so condensation always has the current prompt
1753→		if userPrompt != "" {
1754→			state.LastPrompt = truncatePromptForStorage(userPrompt)
1755→		}
1756→
1757→		// Update transcript path if provided (may change on session resume)
1758→		if transcriptPath != "" && state.TranscriptPath != transcriptPath {
1759→			state.TranscriptPath = transcriptPath
1760→		}
1761→
1762→		// Clear checkpoint IDs on every new prompt.
1763→		// LastCheckpointID is set during PostCommit, cleared at new prompt.
1764→		// TurnCheckpointIDs tracks mid-turn checkpoints for stop-time finalization.
1765→		state.LastCheckpointID = ""
1766→		state.TurnCheckpointIDs = nil
1767→
1768→		// Calculate attribution at prompt start (BEFORE agent makes any changes)
1769→		// This captures user edits since the last checkpoint (or base commit for first prompt).
1770→		// IMPORTANT: Always calculate attribution, even for the first checkpoint, to capture
1771→		// user edits made before the first prompt. The inner CalculatePromptAttribution handles
1772→		// nil lastCheckpointTree by falling back to baseTree.
1773→		promptAttr := s.calculatePromptAttributionAtStart(ctx, repo, state)
1774→		state.PendingPromptAttribution = &promptAttr
1775→
1776→		// Check if HEAD has moved (user pulled/rebased or committed)
1777→		// migrateShadowBranchIfNeeded handles renaming the shadow branch and updating state.BaseCommit
1778→		if _, err := s.migrateShadowBranchIfNeeded(ctx, repo, state); err != nil {
1779→			return fmt.Errorf("failed to check/migrate shadow branch: %w", err)
1780→		}
1781→
1782→		if err := s.saveSessionState(ctx, state); err != nil {
1783→			return fmt.Errorf("failed to update session state: %w", err)
1784→		}
