1786→	}
1787→	// If state exists but BaseCommit is empty, it's a partial state from concurrent warning
1788→	// Continue below to properly initialize it
1789→
1790→	// Initialize new session
1791→	state, err = s.initializeSession(ctx, repo, sessionID, agentType, transcriptPath, userPrompt, model)
1792→	if err != nil {
1793→		return fmt.Errorf("failed to initialize session: %w", err)
1794→	}
1795→
1796→	// Apply phase transition: new session starts as ACTIVE.
1797→	if transErr := TransitionAndLog(ctx, state, session.EventTurnStart, session.TransitionContext{}, session.NoOpActionHandler{}); transErr != nil {
1798→		logging.Warn(logging.WithComponent(ctx, "hooks"), "turn start transition failed",
1799→			slog.String("session_id", sessionID),
1800→			slog.String("error", transErr.Error()))
1801→	}
1802→
1803→	// Calculate attribution for pre-prompt edits
1804→	// This captures any user edits made before the first prompt
1805→	promptAttr := s.calculatePromptAttributionAtStart(ctx, repo, state)
1806→	state.PendingPromptAttribution = &promptAttr
1807→	if err = s.saveSessionState(ctx, state); err != nil {
1808→		return fmt.Errorf("failed to save attribution: %w", err)
1809→	}
1810→
1811→	logging.Info(logging.WithComponent(ctx, "hooks"), "initialized shadow session",
1812→		slog.String("session_id", sessionID))
1813→	return nil
1814→}

