321→func TestHandleLifecycleCompaction_PreservesTranscriptOffset(t *testing.T) {
322→	// Cannot use t.Parallel() because we use t.Chdir()
323→	tmpDir := t.TempDir()
324→	t.Chdir(tmpDir)
325→
326→	// Initialize git repo with a commit (not empty)
327→	setupGitRepoWithCommit(t, tmpDir)
328→	paths.ClearWorktreeRootCache()
329→
330→	// Create .entire directory structure
331→	if err := os.MkdirAll(paths.EntireDir, 0o755); err != nil {
332→		t.Fatalf("Failed to create .entire: %v", err)
333→	}
334→
335→	// Create a transcript file
336→	transcriptPath := filepath.Join(tmpDir, "transcript.jsonl")
337→	transcriptContent := `{"type":"user","message":{"role":"user","content":"test prompt"}}` + "\n"
338→	if err := os.WriteFile(transcriptPath, []byte(transcriptContent), 0o644); err != nil {
339→		t.Fatalf("Failed to create transcript: %v", err)
340→	}
341→
342→	sessionID := "compaction-test-session"
343→
344→	// Create session state with non-zero transcript offset (set by prior condensation)
345→	sessionState := &strategy.SessionState{
346→		SessionID:                 sessionID,
347→		CheckpointTranscriptStart: 50,
348→	}
349→	if err := strategy.SaveSessionState(context.Background(), sessionState); err != nil {
350→		t.Fatalf("Failed to save session state: %v", err)
351→	}
352→
353→	ag := newMockAgent()
354→	event := &agent.Event{
355→		Type:       agent.Compaction,
356→		SessionID:  sessionID,
357→		SessionRef: transcriptPath,
358→	}
359→
360→	// Compaction should NOT reset the transcript offset.
361→	// Many agents (e.g., Gemini) fire pre-compress as a no-op after every tool call;
362→	// resetting the offset causes stale files to re-appear in carry-forward.
363→	err := handleLifecycleCompaction(context.Background(), ag, event)
364→	if err != nil {
365→		t.Logf("handleLifecycleCompaction returned error (expected in minimal test): %v", err)
366→	}
367→
368→	// Verify CheckpointTranscriptStart was preserved (not reset to 0)
369→	loadedState, loadErr := strategy.LoadSessionState(context.Background(), sessionID)
370→	if loadErr != nil {
371→		t.Fatalf("Failed to load session state after compaction: %v", loadErr)
372→	}
373→	if loadedState == nil {
374→		t.Fatal("Session state is nil after compaction")
375→	}
376→	if loadedState.CheckpointTranscriptStart != 50 {
377→		t.Errorf("CheckpointTranscriptStart = %d, want 50 (compaction should preserve offset)",
378→			loadedState.CheckpointTranscriptStart)
379→	}
380→}
