148→				existing, readErr := os.ReadFile(promptPath) //nolint:gosec // session metadata path
149→				var content string
150→				if readErr == nil && len(existing) > 0 {
151→					content = string(existing) + "\n\n---\n\n" + event.Prompt
152→				} else {
153→					content = event.Prompt
154→				}
155→				if writeErr := os.WriteFile(promptPath, []byte(content), 0o600); writeErr != nil {
156→					logging.Warn(logCtx, "failed to write prompt.txt",
157→						slog.String("error", writeErr.Error()))
158→				}
159→			}
160→		}
161→	}
162→
163→	// Ensure strategy setup and initialize session
164→	if err := strategy.EnsureSetup(ctx); err != nil {
